ffi_fn ! { #[doc = " Set the write function for this IO transport."] #[doc = ""] #[doc = " Data from the `buf` pointer should be written to the transport, up to"] #[doc = " `buf_len` bytes. The number of bytes written should be the return value."] #[doc = ""] #[doc = " If there is no data currently available, the callback should create a"] #[doc = " `hyper_waker` from its `hyper_context` argument and register the waker"] #[doc = " with whatever polling mechanism is used to signal when data is available"] #[doc = " later on. The return value should be `HYPER_IO_PENDING`. See the documentation"] #[doc = " for `hyper_waker`."] #[doc = ""] #[doc = " If there is an irrecoverable error reading data, then `HYPER_IO_ERROR`"] #[doc = " should be the return value."] fn hyper_io_set_write (io : * mut hyper_io , func : hyper_io_write_callback) { non_null ! (& mut * io ?= ()) . write = func ;}
}